func readingDeckPreparationTaskURL(bookID string) string {
	return "/reading/books/" + url.PathEscape(bookID) + "/deck/preparations/new"
}

func completedAtLabel(value *time.Time) string {
	if value == nil || value.IsZero() {
		return "Unavailable"
	}
	return value.UTC().Format("2006-01-02 15:04:05 UTC")
}

func deckPreparationRetryLabel(preparation domain.DeckPreparation) string {
	switch {
	case preparation.ProviderOmissions == 1:
		return "Retry 1 omitted card"
	case preparation.ProviderOmissions > 1:
		return fmt.Sprintf("Retry %d omitted cards", preparation.ProviderOmissions)
	default:
		return "Re-prepare with current Meaning evidence"
	}
}

